// Parse the model's JSON defensively.
//
// A model that answers badly must not cost a lead, so anything unparseable
// degrades to a warm lead with a neutral reply instead of throwing. Warm is
// the safe default: it answers the person without paging a human at 2am.
const raw = String($input.first().json.output ?? '').trim();
const lead = $('Wafly Inbound').first().json.body || {};
const cfg = $('Config').first().json;

const fallback = {
  intent: 'unparsed',
  budget_mentioned: false,
  deadline_mentioned: false,
  temperature: 'warm',
  reply: 'Thanks for reaching out. Someone from the team will get back to you shortly.',
};

let parsed = fallback;
try {
  // Models still wrap JSON in a fence now and then even when told not to.
  const cleaned = raw.replace(/^```(?:json)?/i, '').replace(/```$/, '').trim();
  const candidate = JSON.parse(cleaned);
  if (candidate && typeof candidate === 'object') {
    parsed = { ...fallback, ...candidate };
  }
} catch (e) {
  // keep the fallback
}

if (!['hot', 'warm', 'cold'].includes(parsed.temperature)) parsed.temperature = 'warm';
if (!String(parsed.reply || '').trim()) parsed.reply = fallback.reply;

return [{
  json: {
    ...parsed,
    leadPhone: lead.phone,
    leadName: lead.senderName || lead.chatName || 'unknown',
    leadMessage: lead.text?.message || '',
    salesPhone: cfg.salesPhone,
    parsedOk: parsed.intent !== 'unparsed',
  },
}];

